import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import pg from 'pg';
import { type DatabaseConfig, pgPoolConfig } from './config';

/**
 * The SQL migrations generated by drizzle-kit (and hand-edited where noted in the file), resolved
 * from this source file. An app that bundles @shotx/db must ship this folder and pass its path.
 */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../migrations', import.meta.url));

/** Session advisory lock key that serialises concurrent migration runs (e.g. two deploys). */
const MIGRATION_LOCK_KEY = 0x5407_10db;

/**
 * Applies pending migrations on one dedicated connection while holding an advisory lock, so two
 * tasks starting at once don't both migrate. Drizzle records applied migrations in
 * `drizzle.__drizzle_migrations` and applies the pending ones in one transaction.
 */
export async function migrateDatabase(
  config: DatabaseConfig,
  options: { migrationsFolder?: string } = {},
): Promise<void> {
  const migrationsFolder = options.migrationsFolder ?? MIGRATIONS_FOLDER;
  // A single client (the pool size in the config doesn't apply to it).
  const client = new pg.Client(pgPoolConfig(config));
  await client.connect();
  try {
    await client.query('SELECT pg_advisory_lock($1)', [MIGRATION_LOCK_KEY]);
    try {
      await migrate(drizzle({ client }), { migrationsFolder });
    } finally {
      await client.query('SELECT pg_advisory_unlock($1)', [MIGRATION_LOCK_KEY]);
    }
  } finally {
    await client.end();
  }
}
